@layer material, material-high-contrast, size;

:is(:root,:host) {
	--db-focus-outline-color: light-dark(#257FA8, #257FA8);
	--db-divider-bg-color: var(--db-border-default);
	--db-font-weight: normal;
}

:root,
:host {
	background: var(--db-bg-default);
	color: var(--db-text-default);
}

@layer material {

:is(:root,:host) {
	--db-border-default: color-mix(in srgb, light-dark(#D5D7DC, #2A2C31) var(--db-adaptive-transparency, 100%), transparent);
	--db-bg-default: color-mix(in srgb, light-dark(#FFFFFF, #000000) var(--db-adaptive-transparency, 100%), transparent);
	--db-bg-hovered: color-mix(in srgb, light-dark(#E1E2E6, #1E2023) var(--db-adaptive-transparency, 100%), transparent);
	--db-bg-pressed: color-mix(in srgb, light-dark(#BDC1C9, #36393F) var(--db-adaptive-transparency, 100%), transparent);
	--db-border-vibrant: color-mix(in srgb, light-dark(#727782, #727782) var(--db-adaptive-transparency, 100%), transparent);
	--db-border-decorative: color-mix(in srgb, light-dark(#D5D7DC, #2A2C31) var(--db-adaptive-transparency, 100%), transparent);
	--db-text-default: color-mix(in srgb, light-dark(#16181B, #EDEEF0) var(--db-adaptive-transparency, var(--db-emphasis-transparency, 100%)), transparent);
	--db-text-hovered: color-mix(in srgb, light-dark(#484B53, #A6ABB6) var(--db-adaptive-transparency, var(--db-emphasis-transparency, 100%)), transparent);
	--db-text-pressed: color-mix(in srgb, light-dark(#1E2023, #E1E2E6) var(--db-adaptive-transparency, var(--db-emphasis-transparency, 100%)), transparent);
	--db-text-vibrant: color-mix(in srgb, light-dark(#5A5E68, #8A919E) var(--db-adaptive-transparency, var(--db-emphasis-transparency, 100%)), transparent);
	--db-visual-vibrant: color-mix(in srgb, light-dark(#727782, #727782) var(--db-adaptive-transparency, var(--db-emphasis-transparency, 100%)), transparent);
}

